return new{playing=UnityEditor.EditorApplication.isPlaying,scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,modules=UnityEngine.Object.FindObjectsByType<Sandbox.CharacterSystem.ExpressionModule>(UnityEngine.FindObjectsInactive.Include).Select(m=>new{m.name,active=m.gameObject.activeInHierarchy,face=m.Face?m.Face.name:null,m.IsPreviewing}).ToArray(),heads=UnityEngine.Object.FindObjectsByType<UnityEngine.SkinnedMeshRenderer>(UnityEngine.FindObjectsInactive.Include).Where(r=>r.name=="BAKED_head_lod0_mesh").Select(r=>new{r.name,active=r.gameObject.activeInHierarchy,rootActive=r.transform.root.gameObject.activeSelf,r.enabled,pos=r.transform.position.ToString()}).ToArray()};
